// /frontend-react/src/components/ProfilePage.js (FINAL CONFLICT RESOLUTION)

import React, { useState } from 'react';
import HeaderBar from './HeaderBar';

// --- Local Mock Profile Data (remains the same) ---
const mockProfileData = {
    name: "LIM CHIN WEI",
    icNumber: "851020-07-5XXX",
    dateOfBirth: "20 / OCTOBER / 1985",
    address: "NO. 12, JALAN SAGA, KUALA LUMPUR",
    initialEmergencyContact: "CHIN YEE (012-3456789)", 
};

function ProfilePage({ isEasyMode, goToPage, onMenuClick }) {
    const profile = mockProfileData;
    
    const [emergencyContact, setEmergencyContact] = useState(profile.initialEmergencyContact);
    const [isEditing, setIsEditing] = useState(false);

    const handleSaveContact = () => {
        console.log("Profile Updated! New Emergency Contact:", emergencyContact);
        setIsEditing(false);
        alert(`Emergency contact saved as: ${emergencyContact}`);
    };

    // --- FINAL InfoCard Component (Clean Native List Style) ---
    const InfoCard = ({ icon, title, value, isEditable = false }) => (
        <div style={{
            padding: '15px 0', // Slightly reduced vertical padding for better list look
            margin: '0', 
            width: '100%',
            backgroundColor: '#fff',
            borderBottom: '1px solid #e0e0e0', 
            textAlign: 'left',
            position: 'relative', // Context for the EDIT button
        }}>
            <div style={{ 
                padding: '0 20px', 
                // Use Flex to align label/button/value cleanly on one line
                display: 'flex', 
                flexDirection: 'column', 
                alignItems: 'flex-start' 
            }}>
                
                {/* 1. Label and Edit Button Container */}
                <div style={{ 
                    width: '100%', 
                    display: 'flex', 
                    justifyContent: 'space-between', 
                    alignItems: 'center',
                    marginBottom: '5px' // Space below the label line
                }}>
                    {/* Label/Title */}
                    <p style={{ 
                        fontSize: isEasyMode ? '22px' : '15px', 
                        fontWeight: '600', 
                        margin: 0, 
                        color: isEditable && !isEditing ? 'darkorange' : '#6c757d'
                    }}>
                        <span role="img" aria-label={title} style={{marginRight: '10px'}}>{icon}</span>
                        {title.toUpperCase()}
                    </p>

                    {/* EDIT Button (Only visible when not editing) */}
                    {isEditable && !isEditing && (
                        <button
                            onClick={() => setIsEditing(true)}
                            style={{
                                padding: '5px 10px',
                                fontSize: isEasyMode ? '20px' : '12px',
                                backgroundColor: '#1A73E8',
                                color: 'white',
                                border: 'none',
                                borderRadius: '5px',
                                flexShrink: 0, // Prevent button from shrinking
                            }}
                        >
                            EDIT ✍️
                        </button>
                    )}
                </div>
                
                {/* 2. Value Display (Non-Editable) */}
                {!isEditable && (
                    <p style={{ 
                        fontSize: isEasyMode ? '32px' : '20px', 
                        fontWeight: 'bold',
                        margin: '0', 
                        color: '#333' 
                    }}>
                        {value}
                    </p>
                )}
                
                {/* 3. Editable Input Field */}
                {isEditable && (
                    <input
                        type="text"
                        value={emergencyContact}
                        onChange={(e) => setEmergencyContact(e.target.value)}
                        disabled={!isEditing}
                        style={{
                            width: '100%',
                            padding: '10px 0',
                            fontSize: isEasyMode ? '32px' : '20px',
                            border: 'none',
                            borderBottom: isEditing ? '2px solid darkorange' : 'none',
                            backgroundColor: 'transparent',
                            fontWeight: 'bold',
                            color: '#333'
                        }}
                    />
                )}
            </div>
        </div>
    );
    // --- END FINAL InfoCard ---

    return (
        <div style={{ padding: '0', textAlign: 'center' }}>
            <HeaderBar
                title="Profile"
                onBackClick={() => goToPage('dashboard')}
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />

            <h2 style={{ fontSize: isEasyMode ? '40px' : '30px', margin: '30px 0 0 0', color: '#333', padding: '0 20px' }}>
                Personal Details
            </h2>
            
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: '100%', marginTop: '10px' }}>
                
                {/* Non-Editable Fields */}
                <InfoCard icon="👤" title="Name" value={profile.name} isEasyMode={isEasyMode}/>
                <InfoCard icon="🆔" title="IC Number" value={profile.icNumber} isEasyMode={isEasyMode}/>
                <InfoCard icon="🎂" title="Date of Birth" value={profile.dateOfBirth} isEasyMode={isEasyMode}/>
                <InfoCard icon="🏠" title="Address" value={profile.address} isEasyMode={isEasyMode}/>

                {/* Editable Field (The Fix is contained inside the InfoCard now) */}
                <InfoCard 
                    icon="🚨"
                    title="Emergency Contact" 
                    value={emergencyContact} 
                    isEditable={true} 
                    isEasyMode={isEasyMode}
                />

                {/* Save Button (Only Visible when Editing) */}
                {isEditing && (
                    <button
                        onClick={handleSaveContact}
                        style={{
                            padding: '18px 35px', 
                            fontSize: isEasyMode ? '30px' : '20px', 
                            backgroundColor: 'darkorange',
                            color: 'white',
                            border: 'none',
                            borderRadius: '10px',
                            marginTop: '30px',
                            marginBottom: '40px',
                            fontWeight: 'bold',
                        }}
                    >
                        SAVE CHANGES ✅
                    </button>
                )}
            </div>
        </div>
    );
}

export default ProfilePage;
